(root) => {
    const bt = [...root.querySelectorAll('.mg')];
    const lb = bt.map((b) => b.firstElementChild);
    const fk = root.querySelector('.fk');
    const st = { x: 0, y: 0, tx: 0, ty: 0, real: false };
